-- Автопостинг, крок 6: цифри наших постів і тижневий розбір
ALTER TABLE content_posts ADD COLUMN metrics_json TEXT NOT NULL DEFAULT '';
ALTER TABLE content_posts ADD COLUMN metrics_at TEXT;
INSERT INTO changelog (title, body, created_at) VALUES ('Автопостинг: цифри постів і тижневий розбір', 'Після публікації система сама збирає цифри кожного нашого поста з Instagram (охоплення, збереження, репости, перегляди; сторіс — поки вони живі, 24 год): щогодини перший тиждень. Контент → Аналіз → «Наші пости»: таблиця з цифрами і порівнянням із середнім по акаунту. Щопонеділка (тумблер Можливості → «Тижневий розбір контенту») Джері розбирає тиждень: що зайшло, що ні, що змінити — коротко в Telegram і в «Аналізі»; висновки самі йдуть в автоплан наступного місяця. Можна запустити вручну: «Розібрати тиждень».', datetime('now'));
